import React, { useState } from 'react';
import { StyleSheet, Text, View, TextInput, TouchableOpacity, ActivityIndicator, KeyboardAvoidingView, Platform } from 'react-native';
import { api } from '../api';

interface OTPScreenProps {
  mobileNumber: string;
  testOtp?: string;
  onOtpVerified: (token: string, user: any, isNewUser: boolean) => void;
  onGoBack: () => void;
}

export const OTPScreen: React.FC<OTPScreenProps> = ({ mobileNumber, testOtp, onOtpVerified, onGoBack }) => {
  const [otpCode, setOtpCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleVerifyOtp = async () => {
    if (!otpCode || otpCode.length !== 6) {
      setError('Please enter a valid 6-digit code.');
      return;
    }
    setLoading(true);
    setError('');
    try {
      const res = await api.post('/auth/otp/verify', { mobileNumber, otpCode });
      onOtpVerified(res.accessToken, res.user, res.isNewUser);
    } catch (err: any) {
      setError(err.message || 'OTP verification failed. Try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      style={styles.container}
    >
      <View style={styles.card}>
        <Text style={styles.emoji}>🔐</Text>
        <Text style={styles.title}>Confirm OTP</Text>
        <Text style={styles.subtitle}>SENT TO {mobileNumber}</Text>

        {testOtp ? (
          <View style={styles.testOtpBanner}>
            <Text style={styles.testOtpText}>Test OTP Code: <Text style={styles.testOtpCode}>{testOtp}</Text></Text>
          </View>
        ) : null}

        {error ? <Text style={styles.errorText}>{error}</Text> : null}

        <View style={styles.formGroup}>
          <Text style={styles.label}>Enter Code</Text>
          <TextInput
            style={styles.input}
            placeholder="000000"
            placeholderTextColor="#8892b0"
            keyboardType="number-pad"
            maxLength={6}
            value={otpCode}
            onChangeText={(text) => { setOtpCode(text); setError(''); }}
          />
        </View>

        <TouchableOpacity
          style={styles.button}
          onPress={handleVerifyOtp}
          disabled={loading}
        >
          {loading ? (
            <ActivityIndicator color="#0d1117" />
          ) : (
            <Text style={styles.buttonText}>Confirm & Sign In</Text>
          )}
        </TouchableOpacity>

        <TouchableOpacity
          style={styles.backButton}
          onPress={onGoBack}
          disabled={loading}
        >
          <Text style={styles.backButtonText}>Use Different Mobile Number</Text>
        </TouchableOpacity>
      </View>
    </KeyboardAvoidingView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#0d1117',
    alignItems: 'center',
    justifyContent: 'center',
    padding: 24,
  },
  card: {
    backgroundColor: '#161b22',
    borderWidth: 1,
    borderColor: '#21262d',
    borderRadius: 16,
    padding: 32,
    width: '100%',
    maxWidth: 400,
    alignItems: 'center',
  },
  emoji: {
    fontSize: 48,
    marginBottom: 16,
  },
  title: {
    fontSize: 24,
    fontWeight: '800',
    color: '#ffffff',
    textAlign: 'center',
  },
  subtitle: {
    fontSize: 10,
    fontWeight: '700',
    color: '#8892b0',
    letterSpacing: 1.5,
    marginTop: 4,
    marginBottom: 24,
    textAlign: 'center',
  },
  testOtpBanner: {
    backgroundColor: 'rgba(16, 185, 129, 0.12)',
    borderColor: 'rgba(16, 185, 129, 0.25)',
    borderWidth: 1,
    borderRadius: 8,
    paddingVertical: 10,
    paddingHorizontal: 16,
    marginBottom: 20,
    width: '100%',
  },
  testOtpText: {
    color: '#10b981',
    fontSize: 13,
    textAlign: 'center',
    fontWeight: '500',
  },
  testOtpCode: {
    fontWeight: '800',
    fontSize: 14,
  },
  formGroup: {
    width: '100%',
    marginBottom: 20,
  },
  label: {
    color: '#8892b0',
    fontSize: 13,
    fontWeight: '600',
    marginBottom: 8,
  },
  input: {
    backgroundColor: '#0d1117',
    borderWidth: 1,
    borderColor: '#21262d',
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    color: '#ffffff',
    fontSize: 18,
    textAlign: 'center',
    letterSpacing: 4,
    fontWeight: '700',
  },
  button: {
    backgroundColor: '#0ea5e9',
    borderRadius: 8,
    paddingVertical: 14,
    width: '100%',
    alignItems: 'center',
    justifyContent: 'center',
    marginTop: 10,
  },
  buttonText: {
    color: '#0d1117',
    fontSize: 16,
    fontWeight: '700',
  },
  backButton: {
    marginTop: 20,
    paddingVertical: 10,
  },
  backButtonText: {
    color: '#8892b0',
    fontSize: 13,
    fontWeight: '500',
    textDecorationLine: 'underline',
  },
  errorText: {
    color: '#f43f5e',
    fontSize: 14,
    fontWeight: '500',
    marginBottom: 16,
    textAlign: 'center',
  },
});
